<template>
  <div class="">
    <!-- <template v-if="!roles.isAdmin && !roles.isUser"> -->
    <template>
      <b-card no-body class="mr-1" style="">
        <b-card-header class="p-1">
          <h5 class="saj-title">
            <!-- {{ adminSearch }} -->
            <!-- <p>{{ itemsForHR }}</p> -->
            {{ $t("Search Filter") }}
          </h5>
        </b-card-header>
        <b-card-body>
          <b-row style="display: flex;
                   align-items: flex-end;
                  ">
            <b-col cols="12" md="4" class="mb-md-0 " :style="!roles.isAdmin ? `display: none;` : ``">
              <label class="saj-text">{{ $t("Subsidiary") }}:</label>
              <!-- <b-form-select
                v-model="selectedEmployeeID"
                :options="empIDList"
                :value="empIDList"
                class
                :disabled="empIDList.length === 0"="saj-text"
              /> -->
              <!-- {{ selectedSub }} -->
              <v-select v-model="selectedSub" class="saj-text select-size-md" style="background: white" :placeholder="$t('Choose Subsidiary')" :reduce="val => val.value" :options="subList" :value="subList" label="text" @input=" selectedInputAdmin()" />
            </b-col>

            <b-col v-if="roles.isHR || roles.isAdmin" cols="12" md="4" class="mb-md-0 ">
              <label class="saj-text">{{ $t("Department") }}:</label>
              <v-select v-model="selectedDept" class="saj-text select-size-md" style="background: white" :placeholder="$t('Choose Department')" :options="DepartmentList" :reduce="val => val.value" label="text" :disabled="selectedSub === null && roles.isAdmin" @input="selectedDept === null ? selectedDept = '' : ''" />
            </b-col>
            <b-col cols="12" md="4" class="mb-md-0 ">
              <label class="saj-text">{{ $t("Employee Number") }}:</label>
              <!-- <b-form-select
                v-model="selectedEmployeeID"
                :options="empIDList"
                :value="empIDList"
                class
                :disabled="empIDList.length === 0"="saj-text"
              /> -->
              <v-select v-model="selectedEmployeeID" class="saj-text select-size-md" style="background: white" :placeholder="$t('Choose Employee Number')" :disabled="selectedSub === null && roles.isAdmin" :options="empIDList" />
            </b-col>
            <b-col cols="12" md="4" class="mb-md-0">
              <label class="saj-text">{{ $t("Work Location") }}:</label>
              <!-- <b-form-select
                v-model="selectedWork"
                :options="WorkList"
                :value="WorkList"
                class="saj-text"
              /> -->
              <v-select v-model="selectedWork" class="saj-text select-size-md" style="background: white" :placeholder="$t('Choose Work Location')" :options="WorkList" :reduce="work => work.value" label="text" :disabled="selectedSub === null && roles.isAdmin" @input="selectedWork === null ? selectedWork = '' : ''" />
            </b-col>
            <b-col cols="12" md="4" class="mb-md-0 mb-2">
              <label class="saj-text">{{ $t("Position") }}:</label>
              <!-- <b-form-select
                v-model="selectedposition"
                :options="rolesList"
                :value="rolesList"
              /> -->
              <v-select v-model="selectedposition" class="saj-text select-size-md" style="background: white" :placeholder="$t('Choose Position')" :options="rolesList" label="text" :disabled="selectedSub === null && roles.isAdmin" @input="selectedposition === null ? selectedposition = '' : ''" />
            </b-col>
            <b-col cols="12" md="4" class="mb-md-0 mb-2 mt-1">
              <label class="saj-text">{{ $t("Search Name") }}:</label>
              <b-form-input id="icons-search" v-model="searchname" :placeholder="$t('Search Name') + '...'" :disabled="selectedSub === null && roles.isAdmin" />
            </b-col>
            <b-col cols="2" class="mt-1">
              <b-button md="3" variant="primary" class="d-flex justify-content-center saj-button" block @click="adminSearch = true, filterEmployee(), show = true">
                <span class="d-md-none d-lg-block">
                  {{ $t("Search") }} </span>
              </b-button>
            </b-col>
            <b-col cols="2">
              <b-button md="3" variant="primary" class="d-flex justify-content-center saj-button" block @click="clearButton(), show = true, roles.selectedRole === 1 ? adminSearch = false : adminSearch = true">
                <span class="d-md-none d-lg-block"> {{ $t("Clear") }}</span>
              </b-button>
              <!-- {{ items.length }} {{ itemsForHR.length }} -->
            </b-col>
            <b-col cols="8" v-if="roles.isAdmin" style="display: flex; justify-content: flex-end;">
              <b-button variant="link" class="d-flex justify-content-center saj-button" @click="exportReportingList()">
                <span> {{ $t("Export Reporting List") }}</span>
              </b-button>
              <input type="file" ref="fileInput" @change="importReportingList" accept=".xlsx,.xls,.csv" style="display: none;" />
              <b-button variant="link" class="d-flex justify-content-center saj-button" @click="openFileDialog()">
                <span> {{ $t("Import Reporting List") }}</span>
              </b-button>
            </b-col>
          </b-row>
        </b-card-body>
      </b-card>
    </template>
    <div v-if="adminSearch">
      <b-overlay :show="show" rounded="sm" class="">

        <template #overlay>
          <div class="d-flex flex-column align-items-center justify-content-center">
            <b-spinner variant="primary" label="Spinning" />
            <p class="mt-1">
              {{ $t('Fetching Data') }}...
            </p>
          </div>

        </template>
        <template v-if="items.length !== 0 || itemsForHR !== undefined && itemsForHR.length !== 0">
          <transition-group name="list" mode="out-in" class="row">
            <template v-if="roles.selectedRole !== 6 && roles.selectedRole !== 1">

              <div v-for="(item, indexItem) in items" :key="item.employee.id" style="" class="mr-1">
                <template v-if="indexItem < maxList">
                  <b-card no-body class="mb-1 ml-1" style="
                      background: #ffffff;
                      box-shadow: 0px 4px 4px rgba(0, 0, 0, 0.25),
                        0px 0px 41px 9px rgba(0, 0, 0, 0.11);
                      border-radius: 5%;
                      min-height: 22rem;
                      min-width: 25rem;
                      max-height: 22rem;
                      max-width: 25rem;
                      overflow-y: auto;
                      font-size: 1.35rem;
                    ">
                    <b-card-body class="d-flex flex-column justify-content-between p-2" style="height:100%;">
                      <div class="">
                        <b-row>
                          <b-col cols="4">
                            <b-img :src="item.profile_picture.file === null ? require(`@/assets/images/user.png`) : item.profile_picture.file.url" class="" style="object-fit: cover;
                           border-radius: 50%;
                           height: 4em;
                           width: 4em;
                           " />
                          </b-col>
                          <b-col cols="8">
                            <div class="saj-subtitle">
                              {{ item.user.name }}
                            </div>
                            <div class="saj-text">
                              ({{ item.employee.position }})
                            </div>
                          </b-col>
                        </b-row>
                        <b-row class="m-0 mt-2 d-flex ">
                          <b-col cols="2" class="d-flex justify-content-top align-items-start">
                            <div>
                              <feather-icon icon="MailIcon" size="22" stroke="black" />
                            </div>
                          </b-col>
                          <b-col cols="10" class="saj-text">
                            <div>
                              {{ item.user.email }}
                            </div>
                            <div>
                              {{ item.employee.employee_number }}
                            </div>
                            <div>
                              {{ item.employee.mobile_number }}
                            </div>
                            <div>
                              {{ item.employee.branch_name }}
                            </div>
                          </b-col>
                        </b-row>
                      </div>

                      <div>
                        <router-link class="m-0" :to="{ name: 'team-profile-individual', params: { id: item.user.id, subId: subsidiary_id } }">
                          <b-button class="saj-button m-0 mt-1" variant="primary" block>
                            {{ $t("See Details") }}
                          </b-button>
                        </router-link>
                      </div>
                    </b-card-body>

                  </b-card>
                </template>
              </div>
            </template>
            <template v-else>
              <!-- {{ itemsForHR }} -->

              <div v-for="(item, index) in itemsForHR" :key="item.employee_id" style="">
                <template v-if="index < maxListHR">
                  <b-card no-body class="mb-1 ml-1" style="
                      background: #ffffff;
                      box-shadow: 0px 4px 4px rgba(0, 0, 0, 0.25),
                        0px 0px 41px 9px rgba(0, 0, 0, 0.11);
                      border-radius: 5%;
                      min-height: 22rem;
                      min-width: 25rem;
                      max-height: 22rem;
                      max-width: 25rem;
                      overflow-y: auto;
                      font-size: 1.35rem;
                    ">
                    <b-card-body class="d-flex flex-column justify-content-between p-2" style="height:100%;">
                      <div class="">
                        <b-row>
                          <!-- <b-col cols="4">
                    <b-img
                      :src="item.profile_picture.file === null ? require(`@/assets/images/user.png`) : item.profile_picture.file.url"
                      class=""
                      style="object-fit: contain;
                         border-radius: 50%;
                         height: 4em;
                         width: 4em;
                         "
                    />
                  </b-col> -->
                          <b-col cols="8">
                            <div class="saj-subtitle">
                              {{ item.full_name }}
                            </div>
                            <div class="saj-text">
                              ({{ item.position }})
                            </div>
                          </b-col>
                        </b-row>
                        <b-row class="m-0 mt-2 d-flex lign-items-center">
                          <b-col cols="2" class="d-flex justify-content-top align-items-start">
                            <div>
                              <feather-icon icon="MailIcon" size="22" stroke="black" />
                            </div>
                          </b-col>
                          <b-col cols="10" class="saj-text">
                            <div>
                              {{ item.email }}
                            </div>
                            <div>
                              {{ item.employee_number }}
                            </div>
                            <div>
                              {{ item.mobile_number }}
                            </div>
                            <div>
                              {{ item.department }}
                            </div>
                            <div>
                              {{ item.branch }}
                            </div>
                          </b-col>
                        </b-row>
                      </div>

                      <div>
                        <router-link class="m-0" :to="{ name: 'team-profile-individual', params: { id: item.user_id, subId: subsidiary_id } }">
                          <b-button class="saj-button m-0 mt-1" variant="primary" block>
                            {{ $t("See Details") }}
                          </b-button>
                        </router-link>
                      </div>
                    </b-card-body>

                  </b-card>
                </template>
              </div>
            </template>
          </transition-group>
          <b-row v-if="roles.selectedRole === 6 || roles.selectedRole === 1" class="p-1">
            <b-col>
              <div class="d-flex align-items-center justify-content-center">
                <i style="margin-right: 5px" class="fa-solid fa-angles-left saj-page" @click="currentPage = 1, getDetails()" />
                <i class="fa-solid fa-angle-left saj-page" style="" @click="currentPage !== 1 ? currentPage-- : currentPage === 1, getDetails()" />
                <validation-provider #default="{ errors }" :name="$t('Page')" :rules="{
                  required,
                  max_value: lastPage,
                  min_value: 1,
                }">
                  <b-form-input v-model="currentPage" class="p-0 text-center" type="number" style="width: 35px; height: 35px; background-color: red; color: white; border-radius: 20px; margin-right: 5px; margin-left: 5px;" @change="currentPage > 0 && currentPage < lastPage + 1 ? getDetails() : ''" />
                  <small class="text-danger" style="color: #EA5455 !important;
                          position: absolute;
                          white-space: nowrap;
                          right: 25px;
                        ">{{ errors[0] }}</small>
                </validation-provider>
                <i class="fa-solid fa-angle-right saj-page" style="" @click="currentPage < lastPage ? currentPage++ : currentPage === rows, getDetails()" />
                <i class="fa-solid fa-angles-right saj-page" style="margin-left: 5px" @click="currentPage = lastPage, getDetails()" />
              </div>
            </b-col>
          </b-row>
          <div v-if="items.length > 40" class="pointer btn btn-primary mb-1" style="width: 100%;" @click="maxList = maxList + 10">
            {{ $t('See More') }}
          </div>
        </template>
        <template v-else>
          <!-- cantikkan sikit -->

          <div class="saj-text d-flex align-items-center justify-content-center bg-white p-1 m-1" style="font-style: italic; background: rgb(247, 247, 252); text-align: center; height: 500px; border-radius:20px ">

            {{ $t('Team members not available') }}

          </div>
        </template>
      </b-overlay>
    </div>

  </div>
</template>

<script>
import {
  BCard,
  BCardBody,
  BCardHeader,
  BRow,
  BCol,
  BImg,
  BButton,
  BFormInput,
  BOverlay,
  BSpinner,
} from "bootstrap-vue"
import { mapGetters } from 'vuex'
// import _ from 'lodash'
import {
  max_value,
  min_value,
} from 'vee-validate/dist/rules'
import { ValidationProvider, extend } from 'vee-validate'
import { required } from '@validations'
import vSelect from 'vue-select'
import SAJToast from "@/component/saj-toastification.vue"
import FileSaver from 'file-saver'



extend('max_value', max_value)
extend('min_value', min_value)

export default {
  components: {
    BRow,
    BCol,
    BCard,
    BCardBody,
    BCardHeader,
    BButton,
    BImg,
    BFormInput,
    BOverlay,
    BSpinner,
    ValidationProvider,
    vSelect,
  },
  data() {
    return {
      selectedSub: null,
      subList: [],
      adminSearch: true,
      show: true,
      // show: true,
      subsidiary_id: null,
      department_id: null,
      searchname: "",
      selectedposition: "",
      selectedpositionHR: "",
      allRoles: [],
      rolesList: [],
      apiRoleUrl: '',
      apiEmployeeIdUrl: '',
      apiDetailsUrl: '',
      items: [],
      items1: [],
      itemsForHR: [],
      originalItemsForHR: [],
      departmentList: [],
      // searchRoleHR: null,
      searchNameHR: "",
      // searchDepartmentHR: null,
      selectedDepartment: "",

      tempSelectedpositionHR: null,
      tempSearchnameHR: null,
      tempSelectedDepartment: null,
      maxList: 40,
      maxListHR: 40,
      selectedEmployeeID: "",
      empIDList: [],
      allEmpID: [],
      selectedWork: "",
      WorkList: [],
      allWork: [],
      selectedDept: "",
      DepartmentList: [],
      allDept: [],
      isFilter: false,
      required,
      currentPage: 1,
      perPage: null,
      to: null,
      from: null,
      rows: null,
      lastPage: null,
    }
  },
  computed: {
    ...mapGetters(['roles']),
  },
  watch: {
    // eslint-disable-next-line func-names
    '$i18n.locale': function () {
      this.empIDList = this.empIDList.map(x => {
        if (x.value === "") {
          return {
            ...x,
            text: this.$t('Choose Employee Id'),
          }
        }
        return x
      })
    },
  },
  mounted() {
    setTimeout(() => {
      this.checkLoggedUser()
      if (this.roles.selectedRole !== 1) {
        this.getEmployeeID()
      }
    }, 500)
    // setTimeout(() => {
    //   this.getEmployeeID()
    // }, 800)
    // this.getDetails()
    // this.getWorkLocation()
    // this.getDepartment()
    this.getSubsidiaryAll()
    if (this.roles.selectedRole === 1) {
      this.adminSearch = false
    }
  },
  methods: {
    checkLoggedUser() {
      const currentUserRole = this.roles.selectedRole
      switch (currentUserRole) {
        case 3: // Executive
          this.apiEmployeeIdUrl = '/supervisor/getAllEmployee?status=active'
          this.apiRoleUrl = '/position/get_position_by_supervisor'
          this.apiDetailsUrl = '/supervisor/getAllEmployee'
          break
        case 4: // Top Management
          this.apiEmployeeIdUrl = '/tm/getAllEmployeeTM?status=active'
          this.apiRoleUrl = '/position/get_position_by_supervisor'
          this.apiDetailsUrl = '/tm/getEmpSubordinate'
          // this.getAllEmployee()
          break
        case 5: // Head of Department
          this.apiEmployeeIdUrl = '/hod/getEmpByHOD?status=active'
          this.apiRoleUrl = '/position/get_position_by_hod'
          this.apiDetailsUrl = '/hod/getEmpByHOD'
          break
        case 6: // Human Resources
          this.apiEmployeeIdUrl = '/employees/getAllEmployeesNameWithoutPerformance?status=active'
          this.apiRoleUrl = '/position/get_position_by_subsidiary?subsidiary_id=' // dapatkan position untuk HR
          this.apiDetailsUrl = '/subsidiary/get_subsidiary_staff'
          break
        default:
        // console.log('which role: ', currentUserRole)
      }

      if (currentUserRole !== 1) {
        this.getSubsidiary()
      }
      // console.log('check user', this.adminSearch)

      if (this.adminSearch && this.roles.selectedRole === 1) {
        this.apiDetailsUrl = '/subsidiary/get_subsidiary_staff'
        this.getDetails()
        // console.log('masuk ke')
      }
    },
    selectedInputAdmin() {
      // this.selectedSub === null ? (this.selectedDept = '', this.selectedWork = '') : subsidiary_id = this.selectedSub, this.selectedSub === null ? '' :

      if (this.selectedSub === null) {
        this.selectedDept = ''
        this.selectedWork = ''
        this.selectedposition = ''
        this.selectedEmployeeID = ''
      } else {
        this.subsidiary_id = this.selectedSub
        this.getDepartment()
        this.getWorkLocation()
        this.getAllRoles()
        this.getEmployeeID()
      }
    },
    getSubsidiaryAll() {
      this.$axios.get(`${this.$baseUrl}/subsidiary/getAll`).then(response => {
        this.allSubsideriesName = response.data.data.subsidiaries
        // const prevData = _.cloneDeep(response.data.data.subsidiaries)
        // console.log("ALL SUBSIDERIES SINI!", this.allSubsideriesName[0].id);
        // this.subsidiaryID = this.allSubsideriesName[0].id
        // console.log("INI ID!", this.subsidiaryID);
        this.allSubsideriesName.forEach(nameSub => {
          this.subList.push({
            value: nameSub.id,
            text: nameSub.subsidiary_name,
          })
        })
      })
    },
    getEmployeeID() {
      let url = null
      if (this.roles.selectedRole === 1) {
        // eslint-disable-next-line no-template-curly-in-string
        url = `/employees/getAllEmployeesNameWithoutPerformance?subsidiary_id=${this.subsidiary_id}&status=active`
      } else {
        url = `${this.apiEmployeeIdUrl}`
      }
      this.$axios.get(`${this.$baseUrl}${url}`).then(response => {
        // console.log(response)
        this.allEmpID = response.data.data
        if (response.data.success) {
          if (this.roles.selectedRole !== 6 && this.roles.selectedRole !== 1) {
            // if (response.data.data[0] !== undefined){
            this.allEmpID.forEach(empID => {
              this.empIDList.push(empID.employee.employee_number)
            })
            // }
          } else {
            this.allEmpID.forEach(empID => {
              this.empIDList.push(empID.employee_number)
            })
          }
        }
      })
    },
    getDepartment() {
      this.$axios.get(`${this.$baseUrl}/departments/get_departments_by_subsidiary?subsidiary_id=${this.subsidiary_id}`).then(response => {
        this.allDept = response.data.data

        this.DepartmentList = this.allDept.map(x => ({
          text: x.name,
          value: x.id,
        }))
      })
    },
    getWorkLocation() {
      this.$axios.get(`${this.$baseUrl}/branch/get_branch_by_company?company_id=${this.subsidiary_id}`).then(response => {
        this.allWork = response.data.data

        this.WorkList = this.allWork.map(x => ({
          text: x.name,
          value: x.id,
        }))
      })
    },
    // display position kat card
    getAllRoles() {
      let url = null
      if (this.roles.selectedRole === 1) {
        // eslint-disable-next-line no-template-curly-in-string
        url = `/position/get_position_by_subsidiary?subsidiary_id=${this.subsidiary_id}`
      } else if (this.roles.selectedRole !== 6) {
        url = `${this.apiRoleUrl}`
      } else {
        url = `${this.apiRoleUrl}${this.subsidiary_id}`
      }
      this.$axios.get(`${this.$baseUrl}${url}`).then(response => {
        this.allRoles = response.data.data
        this.rolesList = this.allRoles.map(role => (
          role.position
        ))
      }).catch(error => {
        // console.log(error.response)
        if (error.response !== undefined || error.response === null || error.response === 'null') {
          if (!error.response.data.success) {
            this.allRoles = []
            this.rolesList = []
          }
        }
      })
    },
    filterEmployee() {
      this.isFilter = true
      // console.log("tekan search button", this.isFilter)
      const selectedDropdown = this.selectedEmployeeID || this.selectedDept || this.selectedWork || this.selectedposition || this.searchname

      console.log('>> filter here', selectedDropdown)

      if (selectedDropdown !== "" || selectedDropdown !== undefined || selectedDropdown.length !== 0 || selectedDropdown !== null) {
        this.checkLoggedUser()
        this.items = []
        // console.log('filter a')
      } else {
        this.checkLoggedUser()
        this.items = []
        // console.log('filter b')
      }
    },
    getDetails() {
      if (this.roles.selectedRole === 6 || this.roles.selectedRole === 1) {
        this.$axios.get(`${this.$baseUrl}${this.apiDetailsUrl}?subsidiary_id=${this.subsidiary_id}&employee_number=${this.selectedEmployeeID}&employee_name=${this.searchname}&position=${this.selectedposition}&branch_id=${this.selectedWork}&department_id=${this.selectedDept}&page=${this.currentPage}&status=active`).then(response => {
          this.itemsForHR = response.data.data
          const paging = response.data
          // console.log('hr item', response.data)
          this.from = paging.from
          this.to = paging.to
          this.rows = paging.total
          this.perPage = paging.per_page
          this.lastPage = paging.last_page
          this.show = false
          // console.log('masuk HR')
          // console.log('api detail', this.apiDetailsUrl)
        }).catch(() => {
          this.show = false
          this.items = []
        })
      } else {
        // console.log('b')
        // this.getAllEmployee()
        if (this.roles.selectedRole === 4) {
          this.getAllEmployee()
        }
        // console.log('api detail', this.apiDetailsUrl)
        // console.log('emp id', this.selectedEmployeeID)
        this.$axios.get(`${this.$baseUrl}${this.apiDetailsUrl}?employee_number=${this.selectedEmployeeID}&position=${this.selectedposition}&branch_id=${this.selectedWork}&employee_name=${this.searchname}&status=active`).then(response => {
          // this.items = response.data.data
          // console.log('masuk HOD TOP EXEC')
          this.items = this.items.concat(response.data.data)
          this.show = false
          // console.log('filter status HOD TOP EXEC (getDetails)', this.isFilter)
          if (response.data.success === false) {
            this.items = []
          }
        }).catch(() => {
          // console.log(error.message)
          this.items = []
          this.show = false
        })
      }
    },
    getAllEmployee() {
      // console.log('get all employee')
      this.$axios.get(`${this.$baseUrl}/supervisor/getAllEmployee?employee_name=${this.searchname}&position=${this.selectedposition}&branch_id=${this.selectedWork}&employee_number=${this.selectedEmployeeID}&status=active`).then(response => {
        // console.log('Top Punya Employee (getEmployee)')
        // console.log('filter status TOP Management', this.isFilter)
        this.items = response.data.data
        if (response.data.success === false) {
          this.items = []
        }
      })
    },
    getSubsidiary() {
      // console.log('get subsidiary')
      this.$axios.get(`${this.$baseUrl}/users/current_user`).then(response => {
        // console.log('res', response)
        this.subsidiary_id = response.data.data.employee.business_unit
        this.department_id = response.data.data.employee.department_id
        // console.log('dalam api request')
        this.getDetails()
        this.getAllRoles()
        this.getDepartment()
        this.getWorkLocation()
      })
    },
    clearButton() {
      setTimeout(() => {
        if (this.roles.selectedRole === 1) { // if SHR
          this.selectedSub = null
        }
        this.subsidiary_id = null;
        this.selectedpositionHR = ""
        this.searchNameHR = ""
        this.selectedDepartment = ""
        this.selectedposition = ""
        this.searchname = ""
        this.selectedEmployeeID = ""
        this.selectedWork = ""
        this.selectedDept = ""
        this.checkLoggedUser()
        this.items = []
        this.isFilter = false
        this.itemsForHR = []
      }, 500)
      this.currentPage = 1
    },
    exportReportingList() {

      if (!this.subsidiary_id) {
        this.$toast(
          {
            component: SAJToast,
            props: {
              title: `${this.$t('Select Subsidiary')}!`,
              icon: "XIcon",
              variant: 'success',
              iconBg: '#e80202',
              titleColor: '#000',
            },
          },
          {
            position: "top-right",
            type: 'info',
          },
        )
        return;
      }

      this.$toast({
        component: SAJToast,
        props: {
          title: `${this.$t('Your Excel file is currently processing')}.`,
          text: `${this.$t('Please wait, and do not reload or leave this page')}!`,
          icon: "InfoIcon",
          iconBg: '#53b7db',
          variant: "info",
          titleColor: "#000",
        },
      }, {
        position: "top-right",
        type: 'info',
      })

      this.$axios.get(`${this.$baseUrl}/reporting/export?subsidiary_id=${this.subsidiary_id}`, {
        responseType: 'blob',
      }).then(response => {
        if (response.status === 200) {
          FileSaver.saveAs(response.data, "Reporting_List.xlsx")
          this.$toast(
            {
              component: SAJToast,
              props: {
                title: `${this.$t('Your Excel file will be downloaded soon')}!`,
                icon: "CheckCircleIcon",
                variant: "info",
                titleColor: "#000",
              },
            },
            {
              position: "top-right",
              type: 'info',
            },
          )
        }

        //   this.$toast(
        //   {
        //     component: SAJToast,
        //     props: {
        //       title: `${this.$t('Your Excel file is currently processing')}.`,
        //       text: `${this.$t('Please wait, and do not reload or leave this page')}!`,
        //       icon: "InfoIcon",
        //       iconBg: '#53b7db',
        //       variant: "info",
        //       titleColor: "#000",
        //     },
        //   },
        //   {
        //     position: "top-right",
        //     type: 'info',
        //   },
        // )


      })
    },
    openFileDialog() {
      this.$refs.fileInput.click();
    },
    importReportingList(event) {
      if (!event.target.files || !event.target.files.length) {
        this.$toast({
          component: SAJToast,
          props: {
            title: this.$t("Please select a file to import") + "!",
            icon: "XIcon",
            variant: "danger",
            iconBg: "#e80202",
            titleColor: "#000",
          },
        });
        return;
      }

      this.$toast({
        component: SAJToast,
        props: {
          title: `${this.$t('Your Excel file is currently processing')}.`,
          text: `${this.$t('Please wait, and do not reload or leave this page')}!`,
          icon: "InfoIcon",
          iconBg: '#53b7db',
          variant: "info",
          titleColor: "#000",
        },
      }, {
        position: "top-right",
        type: 'info',
      })

      const formData = new FormData();
      formData.append("file", event.target.files[0]);

      this.$axios.post(`${this.$baseUrl}/reporting/import`, formData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      })
        .then((response) => {
          console.log('response?.data', response?.data);

          if (response?.data?.data?.import_status) {

            this.$toast({
              component: SAJToast,
              props: {
                title: this.$t("File imported successfully") + "!",
                icon: "CheckCircleIcon",
                variant: "success",
                iconBg: "#28a745",
                titleColor: "#000",
              },
            });
          } else {
            this.$toast({
              component: SAJToast,
              props: {
                title: this.$t("Import failed"),
                text: response?.data?.message || this.$t("An error occurred during import"),
                icon: "XIcon",
                variant: "danger",
                iconBg: "#e80202",
                titleColor: "#000",
              },
            });
          }
        })
        .catch((error) => {

        });
    },
  },
}
</script>
